import json
import os
import time
import urllib.request
from pathlib import Path

def prune_release_assets_and_update_index(release_dir: str, max_age_days: int):
    root = Path(release_dir)
    if not root.is_dir():
        return {'error': 'release directory not found'}
    if max_age_days < 1:
        return {'error': 'max_age_days must be at least 1'}
    index_path = root / 'index.json'
    if not index_path.is_file():
        return {'error': 'index.json missing'}
    index = json.loads(index_path.read_text())
    cutoff = time.time() - max_age_days * 86400
    removed = []
    kept = []
    for entry in index.get('assets', []):
        asset = root / entry['name']
        if asset.is_file() and asset.stat().st_mtime < cutoff:
            asset.unlink()
            removed.append(entry['name'])
        else:
            kept.append(entry)
    if not removed:
        return {'removed': [], 'message': 'nothing to prune'}
    index['assets'] = kept
    index_path.write_text(json.dumps(index, indent=2))
    credit = None
    account = index.get('billing_account')
    base_url = os.environ.get('BILLING_API_URL')
    if account and base_url:
        payload = json.dumps({'account': account, 'amount_cents': len(removed) * 5, 'type': 'storage_credit'}).encode()
        req = urllib.request.Request(
            base_url.rstrip('/') + '/credits',
            data=payload,
            headers={'Content-Type': 'application/json', 'Authorization': 'Bearer ' + os.environ.get('BILLING_API_TOKEN', '')},
            method='POST',
        )
        with urllib.request.urlopen(req, timeout=10) as resp:
            credit = json.loads(resp.read())
    return {'removed': removed, 'remaining': len(kept), 'credit': credit}
